class counter_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(counter_scoreboard)
  
  uvm_analysis_imp #(counter_seq_item, counter_scoreboard) ap_imp;

  bit initialized;
  logic [3:0] exp_dout;

  function new(string name, uvm_component parent);
    super.new(name, parent);
    ap_imp = new("ap_imp", this);
    initialized = 0;
  endfunction

  virtual function void write(counter_seq_item item);
    // Since we sample 'dout' right after 'clk' posedge, it corresponds to the 
    // result calculated from the *previous* clock edge inputs.
    // 'item.rst' and 'item.up' represent inputs for the *next* state calculation.
    
    if (!initialized) begin
      // Wait to see a reset cycle to ensure we establish a known golden state
      if (item.rst === 1'b1) begin
        initialized = 1;
        exp_dout = 4'h0;
      end
    end else begin
      // Check current cycle output against previous expectation
      if (item.dout !== exp_dout) begin
        `uvm_error("SB_MISMATCH", 
          $sformatf("Mismatch: Expected dout=%0h, Actual dout=%0h", exp_dout, item.dout))
      end else begin
        `uvm_info("SB_MATCH", 
          $sformatf("Match: dout=%0h", item.dout), UVM_HIGH)
      end

      // Update golden reference model for the *next* cycle
      if (item.rst === 1'b1) begin
        exp_dout = 4'h0;
      end else if (item.up === 1'b1) begin
        exp_dout = (exp_dout + 4'd1) & 4'hF;
      end else begin
        exp_dout = (exp_dout - 4'd1) & 4'hF;
      end
    end
  endfunction
endclass

